n=19
base=[[0]*n for _ in range(n)]
centers=[(3,6,8),(4,13,4),(12,14,1),(14,3,2),(10,8,0)]
objects=[]
for r,c,v in centers:
    arms={(r-1,c),(r+1,c),(r,c-1),(r,c+1)}
    objects.append((r,c,v,arms))
    if v: base[r][c]=v
    for rr,cc in arms: base[rr][cc]=3
markers=set((r,c) for r,c,v,arms in objects if v)
for r,c,v,arms in objects:
    pass
# Label each input nonzero marker by its object(s); preserve all base nonzeros.
all_nonzero={(r,c) for r in range(n) for c in range(n) if base[r][c]}
def line_draw(orientation):
    result=[row[:] for row in base]
    for r,c,val,ownarms in objects:
        for dr,dc in ((0,-1),(0,1)) if orientation=='h' else ((-1,0),(1,0)):
            rr,cc=r+dr,c+dc
            while 0<=rr<n and 0<=cc<n:
                if (rr,cc) in all_nonzero and (rr,cc) not in ownarms:
                    break
                if (rr,cc) not in all_nonzero:
                    result[rr][cc]=val
                rr+=dr; cc+=dc
    return result
horiz=line_draw('h')
out=[row[:] for row in horiz]
# vertical rays overwrite prior horizontal colors, except input markers
for r,c,val,ownarms in objects:
    for dr,dc in ((-1,0),(1,0)):
        rr,cc=r+dr,c+dc
        while 0<=rr<n and 0<=cc<n:
            if (rr,cc) in all_nonzero and (rr,cc) not in ownarms:
                break
            if (rr,cc) not in all_nonzero:
                out[rr][cc]=val
            rr+=dr; cc+=dc
print('\n'.join(' '.join(map(str,row)) for row in out))
